insert into public.mcq_questions (topic, stem, options, correct_index, explanation, option_explanations, difficulty, is_clinical, source, generated, verified) values
  ('Cardiology', 'A 64-year-old man with diabetes presents 6 hours after crushing central chest pain. ECG shows ST-elevation in leads II, III and aVF. Which is the most appropriate immediate reperfusion strategy?', array['Primary percutaneous coronary intervention','Thrombolysis with alteplase','Conservative medical therapy only','Immediate exercise stress test'], 0, 'Primary PCI is the preferred reperfusion strategy for ST-elevation MI when it can be delivered within recommended timelines. Thrombolysis is an alternative only if PCI is unavailable.', array['Correct — first-line when available within 120 minutes of first medical contact.','Incorrect — reserved for settings where timely PCI is unavailable.','Incorrect — reperfusion is mandatory in STEMI.','Incorrect — stress testing is contraindicated in acute infarction.'], 'medium', true, 'platform', false, true),
  ('Cardiology', 'Which ECG feature is most characteristic of hyperkalaemia?', array['Peaked T waves','Prolonged PR interval','Delta waves','ST-segment elevation in multiple leads'], 0, 'Tall, peaked (tented) T waves are the earliest and most characteristic ECG sign of hyperkalaemia. Later changes include broadened QRS and loss of P waves.', array['Correct — earliest and most specific ECG finding.','Incorrect — a long PR interval is non-specific.','Incorrect — delta waves suggest pre-excitation (WPW).','Incorrect — diffuse ST elevation has other causes such as pericarditis.'], 'easy', true, 'platform', false, true),
  ('Respiratory', 'A 35-year-old woman with well-controlled asthma develops sudden breathlessness and a popping sensation after vigorous exercise. Chest X-ray shows a small right apical pneumothorax. Which is the best next step?', array['Conservative management with close observation','Immediate needle decompression','Insert an intercostal chest drain','Refer for pleurodesis'], 0, 'A small, primary spontaneous pneumothorax in a stable, asymptomatic patient can be managed conservatively with observation and follow-up X-ray. Interventional drainage is reserved for larger or symptomatic pneumothoraces.', array['Correct — small, stable primary pneumothorax can be observed.','Incorrect — indicated only for tension pneumothorax.','Incorrect — for large or symptomatic pneumothoraces.','Incorrect — reserved for recurrent cases.'], 'medium', true, 'platform', false, true),
  ('Respiratory', 'Which organism is the most common cause of community-acquired pneumonia requiring hospitalisation in adults?', array['Streptococcus pneumoniae','Mycoplasma pneumoniae','Staphylococcus aureus','Legionella pneumophila'], 0, 'Streptococcus pneumoniae remains the most common bacterial cause of community-acquired pneumonia across most settings. Atypical organisms such as Mycoplasma are important in younger patients but less common overall.', array['Correct — the leading cause of CAP worldwide.','Incorrect — common in younger patients, not the overall leader.','Incorrect — more often a hospital-acquired pathogen.','Incorrect — an important but less common cause.'], 'easy', true, 'platform', false, true),
  ('Pharmacology', 'A patient on warfarin has an INR of 6.2 with minor bleeding. Which agent is the most appropriate reversal?', array['Vitamin K (phytomenadione)','Protamine sulfate','Fresh frozen plasma for all patients','Tranexamic acid alone'], 0, 'For a high INR with minor bleeding, vitamin K is the first-line reversal agent. Prothrombin complex concentrate or fresh frozen plasma is reserved for major or life-threatening bleeding. Protamine reverses heparin, not warfarin.', array['Correct — first-line for asymptomatic or minor bleeding with elevated INR.','Incorrect — reverses unfractionated heparin, not warfarin.','Incorrect — only for major bleeding.','Incorrect — an antifibrinolytic, not a warfarin reversal.'], 'medium', true, 'platform', false, true),
  ('Pharmacology', 'Which drug class is first-line for chronic stable angina in reducing cardiovascular events?', array['Antiplatelet agents (aspirin)','Nitrates as monotherapy','Calcium channel blockers only','Short-acting beta-2 agonists'], 0, 'Aspirin is used for secondary prevention to reduce thrombotic events in stable angina. Nitrates relieve symptoms but do not reduce mortality. Beta-blockers and calcium channel blockers provide symptomatic control.', array['Correct — antiplatelet therapy reduces atherothrombotic events.','Incorrect — symptomatic relief, not event reduction.','Incorrect — symptom control, not secondary prevention.','Incorrect — used in asthma, not angina.'], 'medium', true, 'platform', false, true),
  ('Endocrinology', 'A newly diagnosed type 2 diabetic has an HbA1c of 8.6% with no cardiovascular or renal disease and normal BMI. Which is the most appropriate first-line oral agent?', array['Metformin','Glibenclamide','Pioglitazone','Insulin glargine'], 0, 'Metformin is the first-line pharmacotherapy for type 2 diabetes unless contraindicated (e.g. severe renal impairment). It is weight-neutral, affordable and has a strong safety record.', array['Correct — first-line in most guidelines.','Incorrect — sulphonylureas are used later or when metformin is unsuitable.','Incorrect — used in specific circumstances, not first-line generally.','Incorrect — reserved for type 1 or when oral therapy fails.'], 'easy', true, 'platform', false, true),
  ('Endocrinology', 'Which test is the most sensitive screening test for Cushing syndrome?', array['24-hour urinary free cortisol','Random serum cortisol alone','MRI of the pituitary','Dexamethasone suppression with a single cortisol'], 0, 'A 24-hour urinary free cortisol measurement is a sensitive and well-established screening test for Cushing syndrome. Other options include late-night salivary cortisol and the low-dose dexamethasone suppression test.', array['Correct — a first-line screening test.','Incorrect — random serum cortisol is not diagnostic.','Incorrect — localisation, not screening.','Incorrect — needs an appropriate protocol, not a single value.'], 'hard', true, 'platform', false, true),
  ('Renal', 'Which electrolyte disturbance is most commonly associated with chronic kidney disease and is a major driver of bone disease?', array['Hyperphosphataemia','Hypokalaemia','Hypernatraemia','Hypocalcaemia with a low phosphate'], 0, 'Phosphate retention is an early and important consequence of reduced GFR, driving secondary hyperparathyroidism and renal osteodystrophy. Hyperkalaemia is also common but phosphorus is most tied to bone disease.', array['Correct — phosphate retention drives secondary hyperparathyroidism.','Incorrect — hyperkalaemia is common but not the bone-disease driver.','Incorrect — hyponatraemia is more common than hypernatraemia.','Incorrect — calcium is low, but phosphate is high in CKD.'], 'medium', true, 'platform', false, true),
  ('Neurology', 'A 70-year-old man has sudden left-sided weakness and facial droop lasting 40 minutes with complete recovery. What is the most likely diagnosis?', array['Transient ischaemic attack','Ischaemic stroke with permanent deficit','Subarachnoid haemorrhage','Migraine with aura'], 0, 'A focal neurological deficit that resolves completely within 24 hours (here 40 minutes) is a transient ischaemic attack. It is a major warning sign — the patient requires urgent investigation and secondary prevention.', array['Correct — resolves fully within 24 hours.','Incorrect — a stroke would cause persistent deficit.','Incorrect — typically sudden severe headache and meningism.','Incorrect — recurrent, stereotyped headaches with aura.'], 'easy', true, 'platform', false, true),
  ('Neurology', 'Which single first-line treatment is most appropriate for a first unprovoked generalised tonic-clonic seizure in an adult?', array['Sodium valproate or lamotrigine','Carbamazepine only','Phenytoin','Benzodiazepines as lifelong monotherapy'], 0, 'For a first unprovoked generalised seizure, sodium valproate or lamotrigine are common first-line agents. Carbamazepine is preferred for focal seizures. Benzodiazepines are for acute termination, not prophylaxis.', array['Correct — valproate or lamotrigine are first-line for generalised seizures.','Incorrect — better for focal-onset seizures.','Incorrect — older agent, less preferred first-line.','Incorrect — for status epilepticus, not maintenance.'], 'medium', true, 'platform', false, true),
  ('Haematology', 'A microcytic anaemia with normal ferritin, normal transferrin saturation and raised ferritin suggests which condition?', array['Anaemia of chronic disease','Iron deficiency anaemia','Thalassaemia trait','Vitamin B12 deficiency'], 0, 'The combination of microcytosis with normal or raised ferritin and normal transferrin saturation points to anaemia of chronic disease. Iron deficiency typically shows a low ferritin. Thalassaemia trait shows a low MCV with a normal ferritin and a high RBC count.', array['Correct — ferritin is normal/raised with low serum iron.','Incorrect — ferritin is low in iron deficiency.','Incorrect — ferritin is normal but RBC count is high.','Incorrect — B12 deficiency is macrocytic.'], 'hard', true, 'platform', false, true);
